input.sparql:
SELECT ?point ?tsId WHERE {
  ?point (brick:isLocationOf|^brick:hasLocation) / brick:hasPoint ?tempPoint ;
          rdfs:label 'Perimeter_mid_ZN_4' .
  ?tempPoint (brick:hasTimeseries|brick:timeseries) / ref:hasTimeseriesId ?tsId ;
              brick:measuredIn brick:degC ;
              rdf:type brick:Temperature_Sensor .
}
